python3 - <<'E'
p='src/cart.js'
s=open(p).read()
s=s.replace("let i = 1;","let i = 0;")
s=s.replace("""function cartLabel(items) {
  return 'Total: ' + formatPrice(cartTotal(items));
}""","""// Returns the amount (in cents) a discount takes off the given subtotal.
// discount is { type: 'percent', value: 0-100 } or { type: 'fixed', value: cents }.
// The result is never more than the subtotal.
function discountAmount(subtotal, discount) {
  if (!discount) return 0;
  let amount;
  if (discount.type === 'percent') {
    if (!(discount.value >= 0 && discount.value <= 100)) {
      throw new RangeError('percent discount must be between 0 and 100');
    }
    amount = Math.round(subtotal * discount.value / 100);
  } else if (discount.type === 'fixed') {
    if (!(discount.value >= 0)) {
      throw new RangeError('fixed discount must not be negative');
    }
    amount = discount.value;
  } else {
    throw new TypeError('unknown discount type: ' + discount.type);
  }
  return Math.min(amount, subtotal);
}

// Returns the cart total after applying an optional discount.
function discountedTotal(items, discount) {
  const subtotal = cartTotal(items);
  return subtotal - discountAmount(subtotal, discount);
}

function cartLabel(items, discount) {
  return 'Total: ' + formatPrice(discountedTotal(items, discount));
}""")
s=s.replace("{ cartTotal, cartLabel }","{ cartTotal, cartLabel, discountAmount, discountedTotal }")
open(p,'w').write(s)
p='test/cart.test.js'
s=open(p).read()
s=s.replace("{ cartTotal, cartLabel }","{ cartTotal, cartLabel, discountAmount, discountedTotal }")
s+="""
const items = [{ price: 1000, qty: 2 }];

test('percent discount', () => {
  assert.strictEqual(discountedTotal(items, { type: 'percent', value: 10 }), 1800);
});

test('fixed discount is capped at the subtotal', () => {
  assert.strictEqual(discountedTotal(items, { type: 'fixed', value: 500 }), 1500);
  assert.strictEqual(discountedTotal(items, { type: 'fixed', value: 99999 }), 0);
});

test('no discount leaves total unchanged', () => {
  assert.strictEqual(discountedTotal(items), 2000);
});

test('invalid discounts throw', () => {
  assert.throws(() => discountAmount(100, { type: 'percent', value: 150 }), RangeError);
  assert.throws(() => discountAmount(100, { type: 'fixed', value: -1 }), RangeError);
  assert.throws(() => discountAmount(100, { type: 'bogus', value: 1 }), TypeError);
});

test('cartLabel applies a discount', () => {
  assert.strictEqual(cartLabel(items, { type: 'percent', value: 50 }), 'Total: $10.00');
});
"""
open(p,'w').write(s)
E
